      display: none;
      margin-top: 4px;
      font-size: 13px;
      color: #5e6c84;
      cursor: pointer;
      padding: 4px 0;
    }

    .add-card-cancel:hover {
      color: #172b4d;
    }

    .drop-placeholder {
      background: rgba(0, 121, 191, 0.1);
      border: 2px dashed #0079bf;
      border-radius: 6px;
      height: 40px;
      transition: height 0.15s;
    }

    .status-bar {
      position: fixed;
      bottom: 10px;
      right: 10px;
      padding: 6px 12px;
      background: rgba(0,0,0,0.7);
      color: white;
      border-radius: 6px;
      font-size: 12px;
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .status-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: #5aac44;
    }

    .status-dot.disconnected {
      background: #ff5630;
    }

    .status-dot.connecting {
      background: #ffab00;
    }
  </style>
</head>
