      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
      background: #0079bf;
      min-height: 100vh;
      color: #172b4d;
    }

    .board {
      display: flex;
      gap: 12px;
      padding: 20px;
      overflow-x: auto;
      min-height: 100vh;
      align-items: flex-start;
    }

    .column {
      background: #ebecf0;
      border-radius: 8px;
      min-width: 280px;
      max-width: 280px;
      padding: 10px;
      display: flex;
      flex-direction: column;
      max-height: calc(100vh - 40px);
    }

    .column-header {
      font-weight: 600;
      font-size: 14px;
      padding: 6px 8px;
      margin-bottom: 8px;
      display: flex;
      justify-content: space-between;
      align-items: center;
