      background: rgba(0,0,0,0.05);
      outline: none;
      transition: border-color 0.15s;
    }

    .add-card-input:focus {
      border-color: #0079bf;
    }

    .add-card-btn {
      margin-top: 6px;
      padding: 6px 12px;
      background: #0079bf;
      color: white;
      border: none;
