      border-radius: 10px;
      padding: 2px 8px;
      font-size: 12px;
      font-weight: normal;
    }

    .cards-list {
      flex: 1;
      overflow-y: auto;
      min-height: 40px;
      display: flex;
      flex-direction: column;
      gap: 8px;
      padding: 2px;
    }

