      background: white;
      border-radius: 6px;
      padding: 8px 12px;
      box-shadow: 0 1px 2px rgba(0,0,0,0.15);
      cursor: grab;
      font-size: 14px;
      line-height: 1.4;
      word-break: break-word;
      position: relative;
      transition: opacity 0.15s, transform 0.15s;
    }

    .card:hover {
      background: #f4f5f7;
    }

    .card.dragging {
      opacity: 0.5;
      transform: rotate(3deg);
    }

    .card.drag-over {
      border-top: 2px solid #0079bf;
    }

    .card.drop-above {
      border-top: 3px solid #5aac44;
    }

    .card.drop-below {
      border-bottom: 3px solid #5aac44;
    }

    .add-card-form {
      margin-top: 8px;
    }

    .add-card-input {
      width: 100%;
      padding: 8px 12px;
      border: 2px solid transparent;
