// --- PGLite Initialization ---
const db = new PGLite({
  loadDataDir: DATA_DIR,
});

// --- Database Schema & Seeding ---
async function initDatabase() {
  await db.query(`
    CREATE TABLE IF NOT EXISTS columns (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      position REAL NOT NULL
    );
  `);

  await db.query(`
    CREATE TABLE IF NOT EXISTS cards (
      id TEXT PRIMARY KEY,
      column_id TEXT NOT NULL REFERENCES columns(id),
      text TEXT NOT NULL,
      position REAL NOT NULL,
      created_at TIMESTAMP NOT NULL DEFAULT NOW()
    );
  `);

  // Seed default columns if empty
  const { rows: existingColumns } = await db.query('SELECT id FROM columns');
  if (existingColumns.length === 0) {
    const defaults = ['To Do', 'In Progress', 'Done'];
    for (let i = 0; i < defaults.length; i++) {
      await db.query(
        'INSERT INTO columns (id, title, position) VALUES ($1, $2, $3)',
        [generateId(), defaults[i], i]
      );
    }
  }
}

// --- SSE Connection Management ---
const sseClients = new Set();

function broadcast(event, data) {
  const message = `${event} ${JSON.stringify(data)}\n\n`;
  for (const client of sseClients) {
    try {
      client.write(message);
    } catch (e) {
      // Client disconnected, will be cleaned up
    }
  }
}

