    const card = rows[0];

    // Broadcast to all clients
    broadcast('create', { card, columnId: column_id });

    res.status(201).json(card);
  } catch (err) {
    console.error('Error creating card:', err);
    res.status(500).json({ error: 'Failed to create card' });
  }
});

