      // Fetch the updated card
      const { rows } = await db.query(
        'SELECT c.* FROM cards c WHERE c.id = $1',
        [id]
      );
      const updatedCard = rows[0];

      // Broadcast move to all clients
      broadcast('move', {
        card: updatedCard,
        columnId: column_id,
        oldColumnId: oldColumnId
      });

      res.json(updatedCard);
    } catch (txErr) {
      await db.query('ROLLBACK');
      throw txErr;
    }
  } catch (err) {
    console.error('Error moving card:', err);
    res.status(500).json({ error: 'Failed to move card' });
  }
});

// DELETE /api/cards/:id - Delete a card
app.delete('/api/cards/:id', async (req, res) => {
  try {
    const { id } = req.params;

    const { rows } = await db.query(
      'SELECT column_id FROM cards WHERE id = $1',
      [id]
    );

    if (rows.length === 0) {
      return res.status(404).json({ error: 'Card not found' });
    }

    const columnId = rows[0].column_id;

    await db.query('DELETE FROM cards WHERE id = $1', [id]);

    broadcast('delete', { cardId: id, columnId });

    res.json({ success: true });
  } catch (err) {
    console.error('Error deleting card:', err);
    res.status(500).json({ error: 'Failed to delete card' });
  }
});

// GET /api/stream - SSE endpoint
app.get('/api/stream', (req, res) => {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    'Connection': 'keep-alive',
    'X-Accel-Buffering': 'no'
  });

  // Send initial comment to keep connection alive
  res.write(': connected\n\n');

  sseClients.add(res);

  req.on('close', () => {
    sseClients.delete(res);
  });
});

// --- Start Server ---
const PORT = process.env.PORT || 3001;

async function start() {
  try {
    await initDatabase();
    console.log('Database initialized');

    app.listen(PORT, () => {
      console.log(`Server running on http://localhost:${PORT}`);
    });
  } catch (err) {
    console.error('Failed to start server:', err);
    process.exit(1);
  }
}

start();
