      color: white;
      border: none;
      border-radius: 4px;
      font-size: 13px;
      cursor: pointer;
      font-family: inherit;
    }

    .add-card-btn:hover {
      background: #026aa7;
    }

    .add-card-cancel {
      display: none;
      margin-top: 4px;
      font-size: 13px;
      color: #5e6c84;
      cursor: pointer;
      padding: 4px 0;
    }

    .add-card-cancel:hover {
      color: #172b4d;
